<section class="container page-section"><span class="eyebrow">STORE CONTROL</span><h1>Product administration</h1><p class="page-intro">Add products to the catalog or archive items. Protect this area with a proper admin account before deployment.</p><div class="admin-layout"><form class="admin-form" method="post" action="/admin/product/save"><?= csrf_field() ?><h2>Add a product</h2><input type="hidden" name="id" value="0"><label>Product name<input name="name" required maxlength="180"></label><label>Category<input name="category" required placeholder="Electronics"></label><label>Description<textarea name="description" rows="4" required></textarea></label><div class="admin-two"><label>Price<input type="number" min=".01" step=".01" name="price" required></label><label>Stock<input type="number" min="0" name="stock" value="10" required></label></div><label>Image URL<input type="url" name="image_url" required placeholder="https://..."></label><button class="btn btn-primary btn-block">Add product</button></form><div class="admin-catalog"><h2>Catalog <span class="muted">(<?= count($products) ?>)</span></h2><?php foreach($products as $p): ?><div class="admin-product"><img src="<?= e(product_image($p)) ?>" alt=""><div><strong><?= e($p['name']) ?></strong><small><?= e($p['category']) ?> · <?= money($p['price']) ?> · Stock <?= (int)$p['stock'] ?></small></div><form method="post" action="/admin/product/delete" data-confirm="Archive this product?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="link-button danger">Archive</button></form></div><?php endforeach; ?></div></div></section>